!function(){"use strict";function tipoIvaCtrl($scope,mS,toast,form){$scope.data={},$scope.tipoIvas=[],$scope.maxSize=5,$scope.totalRecords=0,$scope.pageIndex=1,$scope.pageSize=10,$scope.recordsQuantity=[5,10,25,50],$scope.get=function(){mS.getData("get","/TipoIva/Get?pageIndex="+$scope.pageIndex+"&pageSize="+$scope.pageSize).then(response=>{"0"!=response.id?(console.log(response.data),$scope.tipoIvas=response.data,$scope.totalRecords=response.data.length>0?response.data[0].totalRecords:0):toast.toastr("warning",response.message,response.titleSms)},error=>console.log(error))},$scope.get(),$scope.pagechanged=function(){$scope.get()},$scope.changePageSize=function(){$scope.pageIndex=1,$scope.get()},$scope.abrirModal=function(data,type){$scope.type=type,$scope.colorHeader=1==type?"bg-info":"bg-success",$scope.iconoModal=1==type?"fa fa-plus":"fa fa-edit",$scope.tituloModal=1==type?"Agregar":"Actualizar",$scope.btnTitulo=1==type?"Guardar":"Actualizar",$scope.btnColor=1==type?" btn-info":"btn-success",$scope.icono=1==type?"fa fa-save":"fa fa-edit",2==type&&($scope.data=data),$("#agregarTipoIva").modal("show")},$scope.$watch("data.descripcion",newVal=>{form.campo(newVal)||1!=$scope.type?$scope.data.codigo="":$scope.data.codigo=newVal.substring(0,3).replace(/[^-A-Za-z0-9]+/g,"").toUpperCase()}),$scope.saveUpdate=function(type){if(form.campo($scope.data.codigoSRI))toast.toastr("warning","Ingrese el Código SRI",$scope.tituloModal);else if(form.campo($scope.data.descripcion))toast.toastr("warning","Ingrese la Descripción",$scope.tituloModal);else if(["null","undefined",""].includes($scope.data.porcentaje))toast.toastr("warning","Ingrese el Porcentaje",$scope.tituloModal);else if(form.campo($scope.data.codigoSRIPri))toast.toastr("warning","Ingrese el Código SRI PRI",$scope.tituloModal);else{var url=1==type?"/TipoIva/Post":"/TipoIva/Put";mS.getData("post",url,$scope.data).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("success",response.message,response.titleSms),void $("#agregarTipoIva").modal("hide")):void 0;toast.toastr("warning",response.message,response.titleSms)})}},$scope.delete=function(data){Swal.fire({html:"<small>Esta seguro/a de eliminar este registro ahora?",icon:"warning",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar",allowOutsideClick:!0}).the(result=>{result.value&&mS.getData("get","/TipoIva/Delete?idTipoIva="+data.idTipoIva).then(response=>{if("0"!=response.id)return"1"==response.id?(toast.toastr("success",response.message,response.titleSms),void $scope.get()):void 0;toast.toastr("warning",response.message,response.titleSms)},error=>console.log(error))})},$("#agregarTipoIva").on("hide.bs.modal",e=>{$scope.data={},$scope.get()})}angular.module("acontPlusApp").controller("tipoIvaCtrl",tipoIvaCtrl),tipoIvaCtrl.$inject=["$scope","mainService","toastService","formulario"]}(window.angular);